<?php
require_once 'functions.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'save';$id=(int)($_POST['id']??0);if($a==='delete'){try{$pdo->prepare("DELETE FROM tbl_kategori WHERE id_kategori=?")->execute([$id]);flash('Kategori dihapus.');}catch(Throwable $e){flash('Kategori masih digunakan produk atau subkategori.','error');}go('kategori.php');}
$name=trim($_POST['nama_kategori']);$parent=$_POST['id_parent']!==''?(int)$_POST['id_parent']:null;$desc=trim($_POST['deskripsi']);if($id)$pdo->prepare("UPDATE tbl_kategori SET nama_kategori=?,id_parent=?,deskripsi=? WHERE id_kategori=?")->execute([$name,$parent,$desc,$id]);else $pdo->prepare("INSERT INTO tbl_kategori(nama_kategori,id_parent,deskripsi) VALUES(?,?,?)")->execute([$name,$parent,$desc]);flash('Kategori disimpan.');go('kategori.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM tbl_kategori WHERE id_kategori=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$pdo->query("SELECT c.*,p.nama_kategori AS induk FROM tbl_kategori c LEFT JOIN tbl_kategori p ON p.id_kategori=c.id_parent ORDER BY c.id_parent,c.nama_kategori")->fetchAll();layout_header('Kategori');
?>
<div class="page-title"><div><span class="eyebrow">PENGELOMPOKAN PRODUK</span><h1>Kategori & Subkategori</h1></div></div><div class="panel"><h3><?=$edit?'Edit kategori':'Tambah kategori'?></h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($edit['id_kategori']??'')?>"><label>Nama kategori</label><input name="nama_kategori" required value="<?=e($edit['nama_kategori']??'')?>"><label>Induk kategori (kosongkan untuk kategori utama)</label><select name="id_parent"><option value="">Kategori utama</option><?php foreach($cats as $c):if(!$c['id_parent']):?><option value="<?=$c['id_kategori']?>" <?=($edit['id_parent']??'')==$c['id_kategori']?'selected':''?>><?=e($c['nama_kategori'])?></option><?php endif;endforeach;?></select><label>Deskripsi</label><textarea name="deskripsi"><?=e($edit['deskripsi']??'')?></textarea><button class="btn btn-primary">Simpan Kategori</button></form></div><div class="section-head"><h2>Daftar kategori</h2></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Induk</th><th>Deskripsi</th><th>Aksi</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=e($c['nama_kategori'])?></td><td><?=e($c['induk']??'Kategori utama')?></td><td><?=e($c['deskripsi'])?></td><td><a class="btn btn-outline btn-sm" href="?edit=<?=$c['id_kategori']?>">Edit</a><form method="post" style="display:inline"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id_kategori']?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus kategori ini?">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_footer(); ?>
